            '\n' ...
            'Filename = ''excsig.txt''; %%name of the text file\n' ...
            'delete(filename) %%delete earlier attempt\n' ...
            'fnid=fopen(filename,''a+''); %%file identifier\n' ...
            'Amax = 511; %%maximum value allowed\n' ...
            '%%Now make integers of each sample:\n' ...
            'smod = round(Amax*signal/max(abs(signal))); \n' ...
            'for ii = 1:length(smod)\n' ...
            '   fprintf(fnid,''%%.0f\\n' ...
            ''',smod(ii))\n' ...
            'end\n' ...
            '\n' ...
         ]);
      ShortHelp='';
