   case {'essd_uic_genpop'}
      Name='Type of generator';
      LongHelp=sprintf( ...
         [ ...
            'The displayed item of this menu determines the parameter values that can \n' ...
            'be set for the excitation signal. In general, these parameters are \n' ...
